abstract class Vehicle07 {private final String reg;Vehicle07(String r){reg=r;}abstract double rate();double fee(int m){return ((m+59)/60)*rate();}@Override public boolean equals(Object o){return o instanceof Vehicle07&&reg.equals(((Vehicle07)o).reg);}@Override public int hashCode(){return reg.hashCode();}@Override public String toString(){return getClass().getSimpleName()+"["+reg+"]";}} class Car07 extends Vehicle07 {Car07(String r){super(r);}@Override double rate(){return 30.0;}} public class Task07Demo {public static void main(String[]x){Car07 a=new Car07("TN02B2"),b=new Car07("TN02B2");System.out.println(a);System.out.println("fee="+a.fee(130));System.out.println("equals="+a.equals(b)+", sameHash="+(a.hashCode()==b.hashCode()));}}